@Test
public void createLaunchCommandWorkerAndPrimaryWorker() throws IOException {
    TensorFlowRunJobParameters parameters = new TensorFlowRunJobParameters();
    parameters.setWorkerLaunchCmd("testWorkerLaunchCommand");
    TensorFlowLaunchCommandFactory launchCommandFactory = createLaunchCommandFactory(parameters);
    Component mockComponent = mock(Component.class);
    AbstractLaunchCommand launchCommand = launchCommandFactory.createLaunchCommand(TensorFlowRole.PRIMARY_WORKER, mockComponent);
    assertTrue(launchCommand instanceof TensorFlowWorkerLaunchCommand);
    launchCommand = launchCommandFactory.createLaunchCommand(TensorFlowRole.WORKER, mockComponent);
    assertTrue(launchCommand instanceof TensorFlowWorkerLaunchCommand);
}

