}

@Test
public void testValidFileSize() throws IOException {
    ClientContext clientContext = mock(ClientContext.class);
    RemoteDirectoryManager remoteDirectoryManager = mock(RemoteDirectoryManager.class);
    when(clientContext.getRemoteDirectoryManager()).thenReturn(remoteDirectoryManager);
